changeSet.sql:
UPDATE event_details SET description = LEFT(description, 900), updated_at = NOW() WHERE description IS NOT NULL AND char_length(description) > 900;
UPDATE event_details SET directions_to_venue = LEFT(directions_to_venue, 600), updated_at = NOW() WHERE directions_to_venue IS NOT NULL AND char_length(directions_to_venue) > 600;
UPDATE event_details SET caption = LEFT(caption, 255), updated_at = NOW() WHERE caption IS NOT NULL AND char_length(caption) > 255;

ALTER TABLE event_details
    ADD CONSTRAINT event_details_description_len_chk
    CHECK (description IS NULL OR char_length(description) <= 900);

ALTER TABLE event_details
    ADD CONSTRAINT event_details_directions_len_chk
    CHECK (directions_to_venue IS NULL OR char_length(directions_to_venue) <= 600);

ALTER TABLE event_details
    ADD CONSTRAINT event_details_caption_len_chk
    CHECK (caption IS NULL OR char_length(caption) <= 255);
